package app.orbit.couple;
import android.appwidget.*;
import android.content.*;
import android.os.Build;
import com.getcapacitor.*;
import com.getcapacitor.annotation.CapacitorPlugin;
@CapacitorPlugin(name="OrbitSurface")
public class SurfacePlugin extends Plugin {
    private MainActivity activity(){return (MainActivity)getActivity();}
    @PluginMethod public void ticket(PluginCall call){getActivity().runOnUiThread(()->{if(activity().privacy==null){call.reject("SURFACE_UNAVAILABLE");return;}call.resolve(new JSObject().put("ticket",activity().privacy.ticket()));});}
    @PluginMethod public void ready(PluginCall call){getActivity().runOnUiThread(()->{if(activity().privacy!=null)activity().privacy.loaded(call.getString("ticket",""));call.resolve();});}
    @PluginMethod public void appearance(PluginCall call){getActivity().runOnUiThread(()->{try{OrbitAppearance.save(getContext(),call.getString("theme","system"),call.getString("accent","#FF6B8A"),call.getString("text","standard"),Boolean.TRUE.equals(call.getBoolean("reduced",false)));if(activity().privacy!=null)activity().privacy.apply();OrbitWidgetProvider.renderAll(getContext());call.resolve();}catch(Exception error){call.reject("APPEARANCE_UNAVAILABLE");}});}
    @PluginMethod public void widgetTarget(PluginCall call){getActivity().runOnUiThread(()->call.resolve(new JSObject().put("route",activity().takeWidgetRoute())));}
    void widgetOpened(){notifyListeners("widgetOpen",new JSObject());}
    private boolean interactive(){return !activity().isDestroyed()&&!activity().isFinishing()&&activity().privacy!=null&&activity().privacy.interactive();}
    private JSObject state(String owner,String couple)throws Exception{
        synchronized(TrackerAuth.class){if(!WidgetEngine.uid(getContext()).equals(owner))throw new Exception("ACCOUNT_CHANGED");var p=WidgetStore.prefs(getContext());if(owner.equals(p.getString("owner",""))&&!couple.equals(p.getString("couple","")))WidgetStore.clear(getContext());boolean own=owner.equals(p.getString("owner",""))&&couple.equals(p.getString("couple",""));AppWidgetManager manager=AppWidgetManager.getInstance(getContext());JSObject result=new JSObject();result.put("kind",own?p.getString("kind","private"):"private");result.put("id",own?p.getString("id",null):null);result.put("installed",OrbitWidgetProvider.ids(getContext()).length);result.put("pinSupported",Build.VERSION.SDK_INT>=26&&manager.isRequestPinAppWidgetSupported());boolean privacy=WidgetEngine.privateMode(getContext()),fresh=false;long checked=0;try{if(own){WidgetSnapshot snapshot=WidgetStore.read(getContext());checked=snapshot.checkedAt;fresh=snapshot.visible(owner,false,false,p.getBoolean("verified",false),System.currentTimeMillis());}}catch(Exception ignored){}String kind=own?p.getString("kind","private"):"private";result.put("covered",privacy||(!kind.equals("private")&&!fresh));result.put("reason",privacy?"privacy":!kind.equals("private")&&!fresh?"refresh":null);result.put("checkedAt",checked);return result;}
    }
    @PluginMethod public void widgetStatus(PluginCall call){getBridge().execute(()->{try{call.resolve(state(OutboxFiles.uuid(call.getString("owner")),OutboxFiles.uuid(call.getString("couple"))));}catch(Exception error){call.reject("WIDGET_UNAVAILABLE");}});}
    @PluginMethod public void widgetSelect(PluginCall call){if(!interactive()){call.reject("UNLOCK_REQUIRED");return;}getBridge().execute(()->{try{String owner=OutboxFiles.uuid(call.getString("owner")),couple=OutboxFiles.uuid(call.getString("couple")),kind=call.getString("kind","");synchronized(TrackerAuth.class){if(!WidgetEngine.uid(getContext()).equals(owner))throw new Exception("ACCOUNT_CHANGED");if(kind.equals("private"))WidgetStore.clear(getContext());else WidgetEngine.select(getContext(),owner,couple,kind,OutboxFiles.uuid(call.getString("id")),call.getInt("version",0).longValue(),this::interactive);}OrbitWidgetProvider.renderAll(getContext());call.resolve(state(owner,couple));}catch(Exception error){call.reject("WIDGET_CHANGED".equals(error.getMessage())?"WIDGET_CHANGED":"WIDGET_UNAVAILABLE");}});}
    @PluginMethod public void widgetRefresh(PluginCall call){getBridge().execute(()->{try{String owner=OutboxFiles.uuid(call.getString("owner")),couple=OutboxFiles.uuid(call.getString("couple"));synchronized(TrackerAuth.class){if(!WidgetEngine.uid(getContext()).equals(owner))throw new Exception("ACCOUNT_CHANGED");var prefs=WidgetStore.prefs(getContext());if(owner.equals(prefs.getString("owner",""))){if(couple.equals(prefs.getString("couple","")))WidgetEngine.refresh(getContext(),()->true);else WidgetStore.clear(getContext());}}OrbitWidgetProvider.renderAll(getContext());call.resolve(state(owner,couple));}catch(Exception error){call.reject("WIDGET_UNAVAILABLE");}});}
    @PluginMethod public void widgetPin(PluginCall call){getActivity().runOnUiThread(()->{if(!interactive()){call.reject("UNLOCK_REQUIRED");return;}AppWidgetManager manager=AppWidgetManager.getInstance(getContext());boolean accepted=Build.VERSION.SDK_INT>=26&&manager.isRequestPinAppWidgetSupported()&&manager.requestPinAppWidget(new ComponentName(getContext(),OrbitWidgetProvider.class),null,null);call.resolve(new JSObject().put("requested",accepted));});}
}
